def parse_molecule(molecule):
    i = 0
    count = {}
    while i < len(molecule):
        if molecule[i].isalpha():
            element = molecule[i]
            i += 1
            num = ''
            while i < len(molecule) and molecule[i].isdigit():
                num += molecule[i]
                i += 1
            count[element] = int(num) if num else 1
        elif molecule[i] == '(':
            stack = ['(']
            j = i + 1
            while stack:
                if molecule[j] == '(':
                    stack.append('(')
                elif molecule[j] == ')':
                    stack.pop()
                j += 1
            sub_count = parse_molecule(molecule[i+1:j-1])
            i = j
            num = ''
            while i < len(molecule) and molecule[i].isdigit():
                num += molecule[i]
                i += 1
            for element, cnt in sub_count.items():
                count[element] = (int(num) if num else 1) * cnt
        else:
            i += 1
    return count

def max_output(input_molecule, k, output_molecule):
    input_count = parse_molecule(input_molecule)
    output_count = parse_molecule(output_molecule)

    min_required = float('inf')
    for element, cnt in output_count.items():
        if element not in input_count:
            return 0
        min_required = min(min_required, input_count[element] // cnt)

    return min_required * k // sum(output_count.values())

