# Define the function to parse a molecular formula
def parse_molecule(formula):
    i = 0
    parsed = []
    while i < len(formula):
        element = formula[i]
        i += 1
        count = ""
        while i < len(formula) and formula[i].isdigit():
            count += formula[i]
            i += 1
        if count == "":
            parsed.append((element, 1))
        else:
            parsed.append((element, int(count)))
    return parsed

# Define the function to calculate the minimum number of molecules needed
def min_required(input_molecule, output_molecule):
    input_counts = Counter(parse_molecule(input_molecule))
    output_counts = Counter(parse_molecule(output_molecule))

    # Calculate the ratio of each element required to produce one output molecule
    ratios = {}
    for element, count in output_counts.items():
        if element not in input_counts:
            return float('inf')
        ratios[element] = count / input_counts[element]

    # Find the minimum ratio which represents the maximum number of output molecules
    return min(ratios.values())

