def main():
    input_lines = sys.stdin.readlines()
    input_molecule, k = input_lines[0].strip().split()
    output_molecule = input_lines[1].strip()

    max_output = 0
    for _ in range(int(k)):
        current_input_molecule = input_molecule
        try:
            current_output = min_required(current_input_molecule, output_molecule)
            if current_output < float('inf'):
                max_output = max(max_output, current_output)
        except ZeroDivisionError:
            pass

    print(max_output)

