def max_molecules(input_molecule, count, output_molecule):
    from collections import defaultdict

    def parse_molecule(molecule):
        i, n = 0, len(molecule)
        elements = defaultdict(int)
        while i < n:
            start = i
            while i < n and molecule[i].isalpha():
                i += 1
            element = molecule[start:i]
            if i < n and molecule[i].isdigit():
                start = i
                while i < n and molecule[i].isdigit():
                    i += 1
                amount = int(molecule[start:i])
            else:
                amount = 1
            elements[element] += amount
        return elements

    input_elements = parse_molecule(input_molecule * count)
    output_elements = parse_molecule(output_molecule)

    min_count = float('inf')
    for element, required in output_elements.items():
        if element not in input_elements:
            return 0
        min_count = min(min_count, input_elements[element] // required)

    return min_count

